/* Indizi del manuale: ragionamento e passaggi specifici per ogni attività.
 * Non partecipano alla valutazione e non modificano il codice dello studente. */
(() => {
 'use strict';
 const hints={
  1:['Il programma è già completo: print invia un messaggio alla console quando Godot esegue _ready(). Non devi aggiungere istruzioni.','Premi Esegui codice. Cerca Ciao GDScript! nel riquadro Output del tuo codice: il risultato della verifica permette di proseguire.'],
  2:['print("") contiene una stringa vuota: le virgolette delimitano il testo, ma al momento non racchiudono alcun carattere.','Scrivi Ciao mondo! fra le due virgolette già presenti. Conserva print, parentesi e rientro dentro _ready(); rispetta maiuscola, spazio e punto esclamativo.'],
  3:['Il simbolo # rende inattiva la parte di riga che lo segue. Qui devi disattivare la seconda stampa e conservare la prima.','Lascia attiva print("Ciao!"). Aggiungi # davanti alla riga print("Arrivederci!"), senza cancellarla. Se commenti entrambe le righe, _ready() resta senza istruzioni eseguibili.'],
  4:['func _ready() apre una funzione: servono i due punti alla fine dell’intestazione e un rientro per le istruzioni che le appartengono.','Completa l’intestazione con : e sposta entrambe le stampe di un livello verso destra. Devono avere lo stesso rientro, perché appartengono allo stesso blocco.'],
  5:['coins rappresenta una quantità intera; speed contiene una parte decimale. Dichiara i due nomi con var prima delle stampe che li leggono.','Usa 25 senza virgolette per coins e 3.5 con il punto per speed. "25" sarebbe una stringa; 3,5 non è un numero decimale in GDScript.'],
  6:['coddy deve contenere testo, quindi il valore va racchiuso fra virgolette. Senza virgolette Godot cercherebbe variabili con quei nomi.','Dichiara coddy prima di print e conserva il testo Sto imparando a programmare con GDScript! esattamente come richiesto. Le virgolette delimitano la stringa, non sono parte del suo contenuto.'],
  7:['is_alive e has_key descrivono stati con due possibilità. Usa i valori booleani true e false, non testi fra virgolette.','Dichiara entrambi i nomi con var prima delle stampe: is_alive deve essere vero e has_key falso. GDScript scrive questi valori in minuscolo.'],
  8:['null indica che weapon non contiene ancora un’arma; non significa una stringa vuota o il numero 0.','Dichiara weapon con null prima della prima stampa. Prima della seconda stampa assegna "Spada" allo stesso nome, senza dichiarare una seconda variabile weapon.'],
  9:['snake_case separa le parole con underscore e usa lettere minuscole. Le stampe indicano già i nomi da usare.','Rinomina le dichiarazioni in player_name, coin_count e is_online. Cambiare soltanto le stampe lascerebbe intatto il problema che questa lezione chiede di correggere.'],
 10:['Il tipo si scrive dopo il nome, preceduto da :; il valore viene dopo =. int, float, String e bool rappresentano dati diversi.','Associa count a int, total a float, grade e user_name a String e is_active a bool. Le stringhe hanno virgolette; il booleano false no.'],
 11:['Con := Godot deduce il tipo dal valore iniziale: un intero, un decimale, un testo e un booleano producono quattro tipi diversi.','Usa := nelle quattro dichiarazioni richieste. Il punto in 99.99 fa dedurre float, le virgolette fanno dedurre String e true senza virgolette fa dedurre bool.'],
 12:['Una costante si dichiara con const, non con var: il suo valore non può essere riassegnato in seguito.','Crea MAX_LIVES e GRAVITY sopra le stampe, conservando nomi in maiuscolo e valori 3 e 9.8. Non serve aggiungere altre print.'],
 13:['Questo riepilogo richiede sia nomi sia tipi corretti: le tre variabili sono int, float e String, mentre MAX_LEVEL è una costante.','Dichiara k minuscola, ratio e player_name usando : oppure :=. Per MAX_LEVEL usa const; K maiuscola non è lo stesso identificatore di k.'],
 14:['Convertire un valore significa passarne il contenuto a int() o float(); non basta cambiare l’etichetta della variabile.','Converti price e level_text con int(), coins con float(). int(99.99) elimina la parte decimale: non arrotonda a 100.'],
 15:['c deve dipendere da a e b tramite la divisione: scrivere direttamente 2.0 non dimostra l’operazione richiesta.','Dichiara prima a e b come numeri decimali, poi calcola c usando i loro nomi. Mantieni la stampa già fornita.'],
 16:['La divisione fra due int elimina la parte frazionaria; convertire un operando in float conserva la quota decimale.','Calcola coins_each usando direttamente total_coins e players. Per exact_share converti total_coins prima della divisione: convertire il risultato intero sarebbe troppo tardi.'],
 17:['L’operatore % restituisce il resto, non il quoziente. Per esempio, 9 diviso 2 ha resto 1.','Dopo aver dichiarato a, b e c, usa rispettivamente i divisori 2, 3 e 10 per d, e e f. Non confondere % con /.'],
 18:['Gli operatori +=, *= e -= modificano il valore già contenuto in count. Ogni passaggio usa il risultato del precedente.','Segui i valori intermedi: 0 diventa 4, poi 8, poi 7. Mantieni questo ordine e non ridichiarare count a ogni passaggio.'],
 19:['Devi soddisfare contemporaneamente prodotto 24 e quoziente intero 6 modificando solo gli operandi a e b.','Prova una coppia e verifica entrambe le espressioni: un prodotto giusto non basta. Ricorda che la divisione fra int tronca la parte decimale.'],
 20:['Un confronto con > produce un bool. L’espressione n1 > n2 non deve essere sostituita con il testo "false".','Dichiara n1 e n2, poi usa i loro nomi nel confronto assegnato a n3. Con 8 e 9 il primo numero non è maggiore del secondo.'],
 21:['and richiede che siano vere sia la soglia di età sia la presenza della patente. Il confronto deve includere anche chi ha esattamente 18 anni.','Imposta age e has_license ai valori richiesti, poi usa >= per l’età minima e combina il confronto con has_license tramite and.'],
 22:['Scegli due interi diversi il cui prodotto superi la somma. La seconda condizione esclude una coppia di numeri uguali.','Verifica a mano prodotto, somma e disuguaglianza prima di eseguire. Cambia soltanto b1 e b2: non sostituire l’espressione di b3 con true.'],
 23:['La prima parte di b4 richiede che esattamente uno fra b1 e b2 sia vero; l’ultima parte richiede che b3 sia falso.','Valuta separatamente (b1 or b2), not (b1 and b2) e not b3. Se b1 e b2 sono entrambi veri, la negazione della loro congiunzione blocca il risultato.'],
 24:['Raggruppa le alternative con parentesi: per entrare serve il livello minimo insieme ad almeno uno fra chiave e mappa.','Per il tesoro servono entrambe le dotazioni e il livello più alto. Per is_lost nega ciascuna dotazione e considera separatamente il livello sotto 3; le parentesi rendono esplicita la precedenza di and e or.'],
 25:['Il ternario di GDScript mette prima il valore da usare quando la condizione è vera, poi if, la condizione, else e l’altro valore.','La condizione è coins >= price: un saldo esattamente uguale al prezzo basta per comprare. Assegna a status una delle due stringhe richieste, non un bool.'],
 26:['Il ramo if viene eseguito solo se a >= b e contemporaneamente b non è minore di 10.','Rendi vera ciascuna parte modificando a e b. Dentro il ramo c diventa 2, poi l’incremento successivo lo porta a 3.'],
 27:['Ordina le soglie del vento dalla più bassa alla più alta: ogni elif viene considerato solo quando i rami precedenti sono falsi.','Gestisci i confini 8, 32 e 64 senza lasciare buchi. Il ramo else deve assegnare Tempesta; non stampare direttamente il caso dell’esempio perché i test cambiano wind.'],
 28:['L’operatore letto in op decide quale calcolo eseguire con n1 e n2. Tutti i rami devono aggiornare result.','Scrivi un ramo per ciascuno dei quattro simboli. Nella divisione conserva i decimali; con 7 e 2 il risultato deve essere 3.5, non 3.'],
 29:['Prima separa gli adulti dai minorenni. Solo nel ramo dei minorenni serve un secondo controllo sulla presenza del genitore.','with_parent è già un bool: controllalo direttamente, senza confrontarlo con la stringa "true". Assegna message in tutti e tre i percorsi.'],
 30:['match confronta season con pattern distinti; il pattern _ gestisce i valori non riconosciuti.','Riunisci "Autunno" e "Aut." nello stesso ramo separandoli con una virgola. Lascia _ per ultimo, altrimenti intercetterebbe anche le stagioni note.'],
 31:['Ogni chiamata a print termina una riga di output. Due messaggi su righe separate richiedono due chiamate.','Sostituisci pass con le due stampe, nello stesso rientro dentro _ready(). Non inserire una virgola fra i due messaggi in un unico print.'],
 32:['Stampa il contenuto delle variabili: scrivere "Ada" a mano renderebbe il messaggio indipendente dal giocatore memorizzato.','Combina le parti fisse delle frasi con player_name, player_level e player_coins. Gli spazi fra le parole devono essere presenti nelle stringhe.'],
 33:['La formattazione usa un segnaposto per ogni valore. Il totale si calcola moltiplicando il prezzo per la quantità.','Usa %s per il nome, %d per la quantità e %.2f per l’importo. L’array dopo % deve fornire i valori nello stesso ordine dei segnaposto.'],
 34:['OS.read_string_from_stdin() restituisce la prossima riga di input come testo. Il saluto deve usare quel testo, non un nome fissato nel codice.','Memorizza il valore letto, poi stampa il prefisso "Ciao, " insieme al nome. La virgola e lo spazio appartengono al messaggio.'],
 35:['Le righe lette sono stringhe: per moltiplicare due numeri decimali devi convertirle entrambe in float.','Esegui due letture distinte e conserva i due valori prima del prodotto. Convertirli in int perderebbe le parti decimali degli input.'],
 36:['Gli anni mancanti si ottengono sottraendo l’età letta da 120. L’ordine della sottrazione è importante.','Converti la riga di input in int prima del calcolo. Inserisci il risultato fra le parti fisse "Mancano " e " anni ai 120".'],
 37:['Il testo "1" e il numero 1 non sono lo stesso tipo. Scegli se confrontare il testo letto oppure convertirlo prima.','Usa due rami: stampa T per 1 e F per l’altro caso. T e F sono stringhe da stampare, non i nomi di variabili.'],
 38:['Questo primo passo del calcolatore introduce soltanto il messaggio iniziale: non servono ancora input o formule.','Inserisci una stampa del titolo richiesto dentro _ready(). Non aggiungere domande o altre righe di console: diventerebbero output in più.'],
 39:['Le letture seguono l’ordine del conto e poi della percentuale. Entrambi possono contenere decimali.','Conserva la stampa iniziale e leggi due float in bill_amount e tip_percentage. In questo passo non stampare ancora questi nuovi valori.'],
 40:['Una percentuale come 9 significa nove centesimi dell’importo: dividila per 100 prima di moltiplicare per il conto.','Calcola prima tip_amount e poi total_amount aggiungendo la mancia al conto originale. Stampare la sola mancia non dà il totale.'],
 41:['Il numero di persone è il terzo input e va letto come int. Il totale da dividere comprende già la mancia.','Calcola amount_per_person dopo total_amount e num_people. Conserva l’ordine delle stampe: titolo, totale, quota di una persona.'],
 42:['Il valore del calcolo non cambia: cambia solo come viene visualizzato. %.2f mostra sempre due cifre decimali.','Formatta separatamente total_amount e amount_per_person con le etichette richieste e il simbolo $. Non arrotondare le variabili prima di dividere il conto.'],
 43:['range esclude il limite finale: per includere n devi far arrivare l’intervallo fino a n + 1.','Il primo valore deve essere 3. Dentro il for stampa il prefisso richiesto e i: stampare n a ogni iterazione ripeterebbe sempre lo stesso numero.'],
 44:['while controlla number prima di ogni divisione. La variabile deve diminuire dentro il ciclo perché la condizione possa diventare falsa.','Dividi per 2 finché number è almeno 3.5, poi stampa fuori dal ciclo. Se l’input è già sotto la soglia, non va dimezzato neppure una volta.'],
 45:['break interrompe subito l’intero ciclo. La posizione del controllo rispetto a print decide se il numero di arresto viene stampato.','Controlla il valore prima di stampare 6, oppure interrompi dopo la stampa di 5. Il risultato non deve contenere 6 né i numeri successivi.'],
 46:['continue salta soltanto l’iterazione corrente. Per eliminare i dispari puoi riconoscerli dal resto della divisione per 2.','Metti il controllo prima della stampa. Se il resto non è 0, passa all’iterazione successiva; i pari devono invece raggiungere print.'],
 47:['Un prodotto cumulativo parte da 1: partire da 0 annullerebbe ogni moltiplicazione, anche per input non nulli.','Moltiplica l’accumulatore per gli interi da 1 a n inclusi. Per n = 0 il ciclo non deve fare operazioni e il risultato deve rimanere 1.'],
 48:['Il terzo argomento di range determina il passo e la direzione. Il limite end rimane escluso anche andando all’indietro.','Usa start, end e step letti dall’input, senza aggiungere 1 a end. Con step negativo l’inizio deve essere maggiore della fine per ottenere elementi.'],
 49:['Il ciclo esterno costruisce le righe; quello interno aggiunge gli asterischi della singola riga.','Reinizializza il testo della riga a ogni giro del ciclo esterno e stampalo dopo il ciclo interno. Non diminuire rows o cols: servono come limiti per tutte le righe.'],
 50:['Il primo numero indica quante letture fare: non è uno dei valori da sommare.','Inizializza la somma a 0, ripeti esattamente n letture e aggiungi ogni numero convertito. Stampa la somma solo dopo aver terminato il ciclo.'],
 51:['Dichiarare print_large_number prepara la funzione; chiamarla nel ciclo è ciò che la fa eseguire n volte.','La nuova func deve stare fuori da _ready(), allo stesso livello di rientro. Dentro il ciclo usa una chiamata con parentesi, non una nuova dichiarazione di funzione.'],
 52:['I parametri di print_product ricevono i valori a e b quando la funzione viene chiamata. Il prodotto si calcola sui parametri.','Definisci la funzione con due parametri e chiamala passando entrambi gli argomenti nell’ordine previsto. Non leggere nuovamente stdin dentro print_product.'],
 53:['return consegna un valore al chiamante; print lo mostra soltanto in console. Qui square_number deve restituire il quadrato.','Dentro la funzione moltiplica il parametro per sé stesso e restituiscilo. In _ready() conserva il valore della chiamata in result prima di stamparlo.'],
 54:['area calcola e restituisce un int; show_area usa quel risultato per stampare e perciò ha ritorno void.','Scrivi i tipi dei due parametri di area e il tipo dopo ->. Puoi passare direttamente il risultato di area(width, height) a show_area.'],
 55:['sigma deve restituire una somma, non stamparla. I test chiamano la funzione direttamente con valori diversi di n.','Per un accumulo parti da 0 e includi anche n nell’intervallo. Il file deve contenere la funzione richiesta, senza _ready() o chiamate di prova.'],
 56:['Le due regole di accesso sono diverse: admin non dipende dalla password, mentre utente richiede quella esatta.','Gestisci i due nomi noti, poi restituisci false per qualsiasi altro nome. Restituisci bool senza virgolette; non stampare il risultato nella funzione.'],
 57:['Un parametro predefinito viene usato solo quando il chiamante omette quell’argomento. Deve stare dopo i parametri obbligatori.','Nella prima chiamata passa solo player; nella seconda passa anche "Bentornato". La funzione deve usare greeting, non stampare sempre lo stesso saluto.'],
 58:['Il progetto FizzBuzz verrà costruito in più passaggi. Qui lo starter prepara l’avvio: completa solo il messaggio iniziale richiesto.','Mantieni il titolo e l’input dove sono previsti dal passo corrente. Le regole basate su 3 e 7 verranno implementate nella funzione dei passaggi successivi.'],
 59:['Controlla per prima la divisibilità sia per 3 sia per 7: se verificassi prima il solo 3, i multipli comuni verrebbero classificati come Fizz.','Usa % per verificare un resto uguale a 0. fizzbuzz restituisce sempre una String; per il caso ordinario converti number con str().'],
 60:['Il ciclo deve chiamare fizzbuzz per ogni numero, non soltanto per il limite finale della partita.','Itera da 1 fino a limit incluso e stampa ogni risultato dentro il ciclo. Conserva la funzione già realizzata e il messaggio di benvenuto una sola volta.'],
 61:['La presenza della cifra 3 è una regola secondaria: si applica solo se nessuna regola di divisibilità ha già scelto Fizz o Buzz.','Controlla la cifra nella versione testuale del numero dopo i casi con %. Così 13 può diventare Quasi Fizz, mentre 30 rimane Fizz.'],
 62:['Un array conserva l’ordine degli elementi e usa le virgole per separarli. I nomi degli alimenti sono stringhe.','Inserisci quattro stringhe dentro le parentesi quadre di shopping_list. Mantieni anche milk come richiesto: cambiare il testo di un elemento cambia l’array verificato.'],
 63:['Gli indici iniziano da 0, quindi i primi count elementi hanno indici da 0 a count - 1. L’indice -1 identifica l’ultimo elemento.','Scorri range(count) e leggi inventory tramite l’indice corrente. La riga Ultimo deve leggere la fine dell’array, non l’ultimo elemento del sottoinsieme stampato.'],
 64:['Per sostituire un elemento assegna un valore alla posizione dell’array; append aggiungerebbe invece un nuovo elemento.','Usa index esattamente come viene letto, compresi i valori negativi validi. L’array deve mantenere lo stesso numero di giocatori dopo la sostituzione.'],
 65:['Aggiungere in fondo, rimuovere per valore e inserire in una posizione sono tre operazioni differenti sugli array.','Usa append per new_item, erase per used_item e insert con indice 0 per mappa. Rimuovere per valore evita di confondere un nome con un indice.'],
 66:['Per il prodotto di una sequenza serve un accumulatore iniziale pari a 1, non a 0.','Scorri numbers e moltiplica il prodotto per ciascun elemento. L’array è già stato letto: non leggere di nuovo il conteggio e non sommare i valori.'],
 67:['Per creare l’inverso senza reverse(), visita gli elementi dall’ultimo al primo e aggiungili a un nuovo array.','Il primo indice è size() - 1; per includere l’indice 0 con passo -1 il limite escluso deve essere -1. Conserva numbers e costruisci il risultato con append.'],
 68:['Array[int] accetta solo numeri interi: la stringa restituita da stdin deve essere convertita prima di append.','Dichiara scores come array tipizzato vuoto, aggiungi i punteggi e ricava il massimo dagli elementi raccolti. Stampa prima l’array e poi la riga Migliore.'],
 69:['Il filtro conserva solo le parole che soddisfano la condizione sulla lunghezza. Non serve modificarle o ordinarle.','Scorri words, controlla length() > 5 e aggiungi a long_words soltanto le parole che superano il controllo. Una parola di 5 caratteri va esclusa.'],
 70:['Il risultato deve contenere gli indici, non i numeri. Per conoscere entrambi scorri le posizioni dell’array.','Per ogni indice controlla il numero corrispondente: basta che sia minore di 50 oppure divisibile per 5. Se soddisfa entrambe le condizioni, aggiungi l’indice una sola volta.'],
 71:['Per trattare p e P allo stesso modo puoi convertire il testo in minuscolo prima del conteggio.','Parti da un contatore a 0 e incrementalo solo quando il carattere corrente è p. Stampa il contatore dopo il ciclo, non il conteggio parziale a ogni carattere.'],
 72:['split separa le parole, mentre join le ricompone. Gli spazi ripetuti possono produrre parti vuote che devono essere escluse.','Puoi usare split(" ", false), oppure filtrare le parti vuote. Unisci poi le parole con separator: non sostituire semplicemente ogni singolo spazio, perché ne conserveresti le ripetizioni.'],
 73:['La porzione centrale dipende dalla parità della dimensione. slice usa un indice iniziale incluso e uno finale escluso.','Calcola prima il centro con la dimensione dell’array. Prevedi il caso con un solo elemento e controlla che il limite finale includa davvero tutti gli elementi centrali richiesti.'],
 74:['Il simbolo + concatena due array; il pattern richiesto ripete il blocco raddoppiato, non i singoli numeri moltiplicati.','Crea il blocco numbers + numbers, poi aggiungilo al risultato repeats volte. Per repeats pari a 0 il risultato deve essere vuoto.'],
 75:['L’operatore not in controlla se un valore manca nel secondo array. La scansione deve seguire l’ordine di first.','Aggiungi al nuovo array ogni elemento di first assente da second. Non usare un insieme per il risultato: eliminerebbe i duplicati che qui devi conservare.'],
 76:['sort() e reverse() modificano l’array su cui vengono chiamati. Per conservare l’originale servono copie distinte.','Stampa l’originale oppure salvalo prima delle modifiche. Ordina una copia e inverti una copia dell’ordinato: non assegnare il risultato di sort(), che non restituisce l’array.'],
 77:['Il dizionario associa ogni chiave tecnica a un valore. Il livello letto da stdin deve essere un int.','Inserisci name, role e level nell’ordine richiesto, usando i valori letti. Le chiavi sono stringhe fisse, mentre il nome dell’eroe e il ruolo cambiano con l’input.'],
 78:['Una chiave di ricerca può non esistere. Verificarla prima dell’accesso evita un errore di Godot per chiave assente.','Memorizza price come float e stock come int. Per la ricerca usa la chiave letta dall’input, non il testo letterale del nome della variabile.'],
 79:['Assegnare un valore a una chiave esistente lo aggiorna; assegnarlo a una chiave nuova aggiunge una coppia.','Aggiorna level, dividi la coppia key:value letta e aggiungila al dizionario. Mantieni numerico il nuovo livello invece di conservarlo come testo.'],
 80:['keys(), values(), size() e has() rispondono a domande diverse sul dizionario già costruito.','Stampa prima tutte le chiavi, poi tutti i valori e infine dimensione e presenza della chiave. Conserva i separatori --- e l’ordine di inserimento.'],
 81:['Per contare un oggetto serve una voce del dizionario inizializzata a 0 la prima volta che compare.','Per ogni oggetto incrementa il suo conteggio, usando has() oppure get con default 0. Stampa dopo aver raccolto tutti gli oggetti, seguendo l’ordine delle chiavi.'],
 82:['Le quantità dell’inventario cambiano in due fasi: prima la raccolta, poi l’utilizzo di un oggetto.','Per un oggetto nuovo parti da quantità 0 prima di aggiungere. Prima di consumare verifica presenza e disponibilità: non creare quantità negative o perdere gli altri articoli.'],
 83:['Il menu è parte dell’output: titolo, riga vuota e opzioni devono apparire nello stesso ordine della consegna.','Una chiamata a print senza argomenti crea la riga vuota. Per questo passo non serve ancora eseguire le opzioni del menu.'],
 84:['Un while true continua finché un break non lo interrompe. Ogni giro deve leggere una nuova scelta.','Confronta la scelta testuale con "5" e interrompi soltanto in quel ramo. Non leggere una sola volta prima del ciclo, altrimenti ripeteresti sempre la stessa scelta.'],
 85:['Le spese devono sopravvivere ai giri del menu: dichiara expenses prima del ciclo, non dentro il ramo di aggiunta.','Solo quando la scelta è 1 leggi un’altra riga, convertila in float e usa append. Il messaggio di conferma va stampato dopo l’inserimento.'],
 86:['L’indice dell’array parte da 0, ma la numerazione mostrata all’utente parte da 1.','Gestisci prima l’array vuoto. Altrimenti scorri gli indici, stampa indice + 1 come numero della voce e leggi la spesa alla posizione originale.'],
 87:['La media è totale diviso numero di spese. Quando l’elenco è vuoto non puoi dividerne la somma per la dimensione.','Gestisci il vuoto prima del calcolo, poi accumula il totale e dividi usando una quantità decimale. Non rinizializzare l’array delle spese nel ramo 3.'],
 88:['clear() svuota l’array esistente, così anche le operazioni successive vedono che non ci sono più spese.','Esegui lo svuotamento nel ramo 4 e stampa la conferma una volta. Verifica una sequenza aggiungi, cancella, visualizza: l’ultimo comando deve rilevare il vuoto.'],
 89:['La scelta non valida è il caso residuo dopo aver riconosciuto tutte le opzioni da 1 a 5.','Metti il messaggio nel ramo else della catena del menu. Non terminare il ciclo in questo caso: il programma deve permettere una nuova scelta.'],
 90:['La larghezza cresce di 2 a ogni riga: la sequenza degli asterischi è 1, 3, 5 fino a n.','Usa un passo 2 e costruisci ogni riga con la quantità corrente di asterischi. La piramide richiesta è piatta: non aggiungere spazi iniziali per centrarla.'],
 91:['Dopo aver trovato un’occorrenza riprendi la ricerca una posizione più avanti, non dopo tutta la lunghezza del pattern: così conservi le sovrapposizioni.','Raccogli gli indici trovati e ricava da essi presenza e conteggio. Restituisci i tre elementi nell’ordine richiesto e gestisci anche il caso senza corrispondenze.'],
 92:['prices e items sono paralleli: lo stesso indice collega un prezzo al nome dell’articolo corrispondente.','Controlla ogni prezzo rispetto a budget_per_item, includendo l’uguaglianza. Seleziona il nome allo stesso indice; non sommare i prezzi per trasformare il limite per articolo in un budget totale.'],
 93:['Ogni riga richiede una trasformazione diversa: capitalizzazione, inversione, prefisso in maiuscolo e riempimento del punteggio con zeri.','Mantieni player_name e score originali per poterli riusare. Per il punteggio usa pad_zeros o lpad con "0": gli zeri vanno aggiunti a sinistra, non a destra.'],
 94:['L’email deve soddisfare tutte le condizioni contemporaneamente. Un controllo sul solo carattere @ accetterebbe indirizzi incompleti.','Conta gli @, escludi spazi e @ iniziale, poi controlla il suffisso sulla versione in minuscolo. Usa and fra le regole e or fra le tre estensioni consentite.'],
 95:['L’ordine delle trasformazioni dello slug conta: ripulisci i bordi, converti in minuscolo e poi sostituisci i caratteri indicati.','Ogni replace restituisce una nuova stringa: riassegna il risultato oppure concatena i metodi. Non rimuovere le lettere accentate o altri simboli che la consegna non chiede di cambiare.'],
 96:['Dopo split sulle virgole devi ripulire ciascuna parola separatamente. Il confronto della lunghezza usa le parole senza spazi esterni.','Conserva la prima parola quando due hanno la stessa lunghezza: aggiorna il massimo solo per una parola strettamente più lunga. Per la riga unita usa il separatore " > ".'],
 97:['Normalizza raw prima dei controlli: le regole di lunghezza e caratteri devono essere applicate al nome ripulito.','Controlla gli estremi 3 e 16 inclusi, gli spazi e il primo carattere. Esamina anche i caratteri consentiti indicati nella consegna; non accettare un nome solo perché ha la lunghezza giusta.'],
 98:['In match la costante SECRET rappresenta il valore da confrontare; var nome cattura invece qualunque valore rimasto.','Metti prima SECRET e 0, poi il pattern di associazione. Nel messaggio dell’ultimo ramo usa il valore catturato, non una nuova lettura di input.'],
 99:['Una guardia restringe un pattern con una condizione. Ogni fascia deve includere sia il limite inferiore sia quello superiore.','Ordina i rami per fascia e lascia un caso predefinito per età negative o oltre 120. Non far rientrare 13 nel ramo dei bambini o 65 in quello degli adulti.'],
100:['I pattern di array distinguono forma e contenuto. Il punto [0, 0] è più specifico dei pattern con un solo asse fissato a 0.','Controlla prima l’origine, poi i singoli assi e infine il caso generale. Cattura la coordinata variabile per inserirla nel messaggio, mantenendo x e y nel loro ordine.'],
101:['Un pattern di dizionario può richiedere determinate chiavi e catturare i loro valori. I campi dell’evento restano stringhe.','Usa le chiavi type, dir e damage senza tradurle. Se il pattern deve accettare anche altre chiavi, usa la forma aperta con ..; converti damage solo quando serve un numero.'],
102:['L’appartenenza all’array names riguarda gli elementi; quella al dizionario grades riguarda le chiavi, non i voti memorizzati.','Esegui separatamente i controlli su classe e voto. Prima di usare il voto letto come numero, verifica o converti il testo secondo la consegna.'],
103:['Normalizzare e dividere il comando produce un array di parole adatto ai pattern di match. Una riga vuota non deve creare un comando valido.','Usa strip_edges, to_lower e split senza parti vuote. Gestisci esci interrompendo il ciclo; nei comandi con argomenti usa valori catturati dai pattern invece di confrontare l’intera riga.'],
104:['Un array 2D è un array di righe; ogni riga contiene cinque celle. La dimensione esterna conta le righe, quella di una riga conta le colonne.','Scrivi quattro array interni distinti dentro level. Per le colonne leggi size() dalla prima riga, non dall’array esterno.'],
105:['Per leggere grid[row][col] devi prima sapere che row esiste e soltanto dopo controllare col nella riga scelta.','Verifica anche gli indici negativi prima di qualsiasi accesso. Per le colonne usa la dimensione di grid[row]: una griglia può avere righe di lunghezze diverse.'],
106:['Costruisci una riga nuova per ogni iterazione esterna, poi aggiungila alla griglia: riusare lo stesso array collegherebbe le righe fra loro.','Riempi le celle col simbolo di sfondo e imposta il giocatore alla coppia di indici letta. Ricorda che si accede prima alla riga e poi alla colonna.'],
107:['Una coppia di cicli visita tutte le celle. Somma, massimo e conteggio dei pari sono tre accumuli distinti.','Inizializza il massimo con una cella reale, non con 0, per gestire griglie di soli numeri negativi. Restituisci somma, massimo e conteggio nell’ordine richiesto.'],
108:['Ogni riga del triangolo ha una lunghezza diversa e deve essere costruita in un array nuovo.','Gli indici di GDScript partono da 0, mentre la formula della consegna numera righe e colonne da 1. Aggiungi 1 agli indici usati nel prodotto.'],
109:['Nella diagonale principale gli indici coincidono; in quella secondaria la somma degli indici è dimensione - 1.','Per righe, colonne e bordi separa la raccolta dei valori dalla stampa. Unisci i valori con uno spazio soltanto, evitando uno spazio in più alla fine della riga.'],
110:['Una vittoria richiede tre simboli uguali e diversi da ".". Controlla righe, colonne e le due diagonali.','Cerca un vincitore prima di decidere pareggio o partita in corso. Una riga di tre caselle vuote non è una vittoria.'],
111:['Per cercare reparto/articolo devi verificare prima il reparto e poi la chiave nel dizionario interno.','Non accedere subito con due parentesi: se manca il reparto, il primo accesso fallisce. Usa i messaggi previsti per le consultazioni assenti e conserva l’ordine delle richieste.'],
112:['Ogni giocatore è un nuovo dizionario con name e score. Il confronto dei punteggi deve essere numerico.','Converti score in int e conserva il giocatore migliore durante la scansione. In caso di parità mantieni quello previsto dalla consegna, senza sovrascrivere il migliore per un pareggio non richiesto.'],
113:['Le impostazioni predefinite servono a riempire soltanto i campi mancanti; non devono cancellare le preferenze già salvate.','Aggiungi i default con merge senza sovrascrittura oppure con has per ciascuna chiave. Verifica un salvataggio che possiede già una delle impostazioni.'],
114:['Una copia superficiale condivide ancora i dizionari interni. I nemici devono avere copie profonde e indipendenti del modello.','Usa duplicate(true) per ogni nemico prima di assegnare id e bonus hp. Modificare un nemico non deve alterare template o quelli generati in precedenza.'],
115:['Il dizionario dei conteggi parte vuoto; ogni elemento letto aumenta la propria frequenza. Numeri e stringhe restano chiavi del loro tipo originale.','Usa get(elemento, 0) per gestire la prima comparsa e restituisci il dizionario dopo il ciclo. Non convertire tutte le chiavi in testo e non ordinare le chiavi.'],
116:['display_menu deve occuparsi solo delle righe del menu; separarla dall’avvio permette di richiamarla senza duplicare il titolo.','Definisci la funzione fuori da _ready() e chiamala dove richiesto. Mantieni ordine, numeri e messaggi delle opzioni senza introdurre nuove letture di stdin.'],
117:['La rubrica associa il nome a un dizionario di dettagli. L’aggiunta deve modificare la rubrica esistente, non ricrearla vuota a ogni scelta.','Leggi nome, telefono, email e indirizzo nell’ordine del comando. Conserva phone, email e address come chiavi tecniche e gestisci i duplicati secondo la consegna.'],
118:['view_contact deve leggere un nome e cercarlo nelle chiavi della rubrica prima di accedere ai dettagli.','Se il contatto esiste stampa i quattro campi nell’ordine richiesto. Se manca, stampa il solo messaggio di assenza e non tentare l’accesso al dizionario interno.'],
119:['La verifica di esistenza viene prima delle tre nuove letture: per un nome assente non devi consumare input destinato al comando successivo.','Per un contatto presente aggiorna phone, email e address nel suo dizionario. Il nome resta la chiave della stessa voce della rubrica.'],
120:['Eliminare un contatto significa rimuovere la coppia associata al suo nome, non svuotare l’intera rubrica.','Controlla has(nome), poi usa erase nel ramo positivo e il messaggio di assenza nell’altro. Gli altri contatti devono restare disponibili.'],
121:['Elencare i contatti non richiede nuove letture. Scorri le chiavi nell’ordine in cui sono state aggiunte.','Gestisci prima la rubrica vuota. Per ciascun nome leggi i dettagli della sua voce, conservando il formato usato per la visualizzazione singola.'],
122:['match choice sostituisce la scelta del ramo, non il ciclo che continua a leggere il menu. Le opzioni sono stringhe.','Richiama la funzione appropriata nei pattern da "1" a "5", usa break per "6" e _ per una scelta non valida. Un pattern sconosciuto non deve interrompere il ciclo.'],
123:['Un Dictionary può simulare un insieme: le chiavi sono uniche, perciò aggiungere due volte la stessa medaglia non aumenta la dimensione.','Memorizza ciascuna medaglia come chiave di badges e ricava i membri con keys(). Non usare un array senza controlli, perché conserverebbe i doppioni.'],
124:['Costruire guests dalle chiavi di un dizionario elimina i nomi ripetuti dall’elenco iniziale.','Per ogni persona in arrivo verifica l’appartenenza allo stesso insieme. La dimensione iniziale conta gli invitati diversi, non il numero totale di parole lette.'],
125:['Prima di aggiungere o rimuovere devi distinguere presenza e assenza: lo stesso comando può produrre messaggi diversi a seconda dello stato.','Usa has(item) e poi modifica inventory nel ramo adatto. Una rimozione riuscita deve influenzare anche i comandi successivi sullo stesso articolo.'],
126:['L’unione contiene elementi presenti in almeno uno dei due insiemi; l’intersezione solo quelli presenti in entrambi.','Costruisci i risultati senza duplicare chiavi. Mantieni l’ordine richiesto: nell’unione considera prima first e poi gli elementi nuovi di second.'],
127:['La differenza needed meno packed identifica ciò che manca; invertirla identifica ciò che hai messo in più.','Scorri separatamente i due insiemi e usa not in nell’altro. Non scambiare l’etichetta Mancano con il risultato della differenza opposta.'],
128:['Per conservare la prima comparsa, visita numbers in ordine e tieni traccia di ciò che hai già incontrato.','Aggiungi al risultato solo i numeri non ancora visti e registrali nell’insieme di supporto. Non ordinare l’array e non modificare quello ricevuto.'],
129:['L’enum dà nomi ai valori numerici del meteo e va dichiarato fuori da _ready(), al livello dello script.','Dichiara Weather con le quattro opzioni nell’ordine indicato e confronta weather con Weather.SUNNY e le altre costanti, senza sostituirle con numeri sparsi.'],
130:['Impostando il primo valore dell’enum a 1, quelli successivi aumentano automaticamente di uno.','Usa il valore di Difficulty per moltiplicare il danno base. EASY non deve valere 0: annullerebbe il danno anziché rappresentare la difficoltà più bassa.'],
131:['Le chiavi dell’enum sono nomi e i suoi valori sono numeri. Per avanzare nella settimana serve un ritorno circolare dopo l’ultimo giorno.','Aggiungi lo spostamento al valore del giorno e usa il resto della divisione per 7. Riporta il risultato al nome italiano previsto, senza perdere gli accenti.'],
132:['Una funzione può riunire più costanti dello stesso enum in un solo ramo di match.','Raggruppa WALK e RUN, poi JUMP e FALL. Ogni ramo di describe deve restituire la descrizione, non stamparla.'],
133:['Le tre funzioni rispondono a domande diverse sul medesimo TrafficLight: azione del conducente, durata e stato successivo.','Scrivi un match in ciascuna funzione e usa le costanti dell’enum. Controlla un ciclo completo di transizioni per verificare che ritorni al colore iniziale.'],
134:['student_records è il contenitore condiviso dei passaggi successivi. In questo primo passo organizza il ciclo dei comandi e la sua uscita.','Leggi un comando a ogni iterazione e interrompi quando arriva quello di chiusura. Non creare una nuova rubrica di studenti dentro il ciclo.'],
135:['Un nome già presente non deve essere sovrascritto: controllalo prima di creare il record dello studente.','Per un nuovo studente prepara età, array dei voti vuoto e corsi nella struttura richiesta. I corsi rappresentano un insieme: non devono diventare duplicati.'],
136:['Per aggiungere un voto serve uno studente già registrato. Il voto deve entrare nell’array del suo record, non in un array temporaneo scollegato.','Nel caso assente stampa l’errore ed esci dalla funzione. Nel caso presente usa append sul campo grades, lasciando intatti età e corsi.'],
137:['is_enrolled restituisce un bool ottenuto controllando il corso nel record dello studente.','Verifica prima l’esistenza del nome. Per uno studente presente usa l’appartenenza al campo courses; non cercare il corso fra le chiavi esterne student_records.'],
138:['La media richiede almeno un voto e una divisione decimale. I casi assente e senza voti hanno il valore sentinella previsto.','Gestisci i casi non validi prima di dividere, poi somma grades e dividi per la sua dimensione. Restituisci il float invece di stampare dentro la funzione.'],
139:['La ricerca per corso deve esaminare il campo courses di ogni studente e raccogliere i nomi corrispondenti.','Scorri student_records nell’ordine di inserimento. Aggiungi il nome una sola volta quando il corso è presente; un corso vuoto di iscritti produce un array vuoto.'],
140:['Per essere fra i migliori serve una media valida e strettamente maggiore della soglia. Il valore sentinella di una media assente non è un voto.','Riusa il calcolo della media per ogni studente e scarta chi non ha voti. Confronta con >, non >=, e conserva l’ordine dei record.'],
141:['Il totale della cassa comprende il denaro iniziale e ogni vendita della giornata: l’accumulatore non deve partire sempre da 0.','Parti dal denaro già presente, poi aggiungi i numeri della prima riga. Se non ci sono vendite, il risultato deve coincidere con il saldo iniziale.'],
142:['Minimo e massimo si ricavano confrontando i valori; per le parole il confronto è lessicografico, non basato sulla lunghezza.','Applica min() e max() agli array predisposti secondo la consegna. Non usare sempre 0 come minimo iniziale, perché gli input possono avere valori tutti maggiori o tutti minori di 0.'],
143:['Il comparatore di sort_custom deve dire se a precede b. Per la lunghezza uguale serve un secondo criterio alfabetico.','Confronta prima length(); solo in parità confronta le stringhe. Per conservare sia crescente sia decrescente, copia l’array prima delle operazioni che lo modificano.'],
144:['Per cambiare l’ordine di inserimento del dizionario, ordina prima le sue chiavi in base ai valori associati e ricrea poi il contenitore.','Il comparatore deve leggere data[a] e data[b], non confrontare i nomi delle chiavi. Inserisci le coppie in un dizionario nuovo nell’ordine ordinato.'],
145:['Una funzione può restituire un array per consegnare più informazioni insieme. La posizione di ciascun elemento ne determina il significato.','Chiama get_student_info una volta sola e leggi gli indici 0, 1 e 2 per nome, età e specializzazione. Non confondere un Array con tre return separati.'],
146:['Una lambda è una funzione conservata in una variabile. Il suo corpo usa i parametri x, y e z ricevuti alla chiamata.','Assegna la lambda a multiply e richiamala con call(a, b, c). La funzione deve restituire il prodotto, non limitarsi a stamparlo.'],
147:['La lambda deve coprire tre casi esclusivi: maggiore di zero, uguale a zero e minore di zero.','Conserva il Callable in categorize_number e chiamalo sul numero letto. Restituisci le tre stringhe con la capitalizzazione richiesta, senza trattare 0 come positivo.'],
148:['Ogni elemento da ordinare è una coppia: l’indice 1 contiene il numero, l’indice 0 il nome da usare in caso di parità.','Nella lambda confronta prima i numeri e poi i nomi. sort_custom modifica data e restituisce void: dopo averlo chiamato, restituisci data separatamente.'],
149:['La ricorsione ha bisogno di un caso di arresto. Qui lo 0 deve essere stampato, ma non deve produrre un’altra chiamata con un numero negativo.','Stampa il numero corrente e chiama count_down con il precedente solo finché devi ancora raggiungere 0. Non aggiungere un ciclo alla funzione ricorsiva.'],
150:['I due casi base di Fibonacci sono diversi: la prima posizione vale 0 e la seconda vale 1.','Restituisci direttamente i casi base; per le altre posizioni combina le due chiamate precedenti. Non confondere il numero di posizione n con il valore della sequenza.'],
151:['Per ogni elemento devi distinguere numero e array. Se è un array, il suo contributo va calcolato richiamando sum_nested.','Parti da totale 0, aggiungi direttamente i numeri e somma il valore restituito dalla chiamata ricorsiva per gli array. L’array vuoto restituisce 0 senza casi speciali aggiuntivi.'],
152:['map costruisce un nuovo array applicando la stessa trasformazione a ogni elemento. La lambda deve restituire il testo in maiuscolo.','Usa to_upper() sul parametro della lambda e restituisci il risultato di map(). Non stampare i valori e non introdurre un ciclo esterno.'],
153:['filter conserva un elemento quando la lambda restituisce true. La condizione riguarda la lunghezza della singola stringa.','Usa length() > 5 nel predicato. Un testo di cinque caratteri va escluso; filter deve mantenere l’ordine delle stringhe che superano il controllo.'],
154:['reduce passa alla lambda un accumulatore e il prossimo elemento. Somma, prodotto e massimo richiedono accumulatori con significati diversi.','Per il prodotto scegli un inizio che non annulli la moltiplicazione. Per il massimo confronta accumulatore ed elemento e restituisci quello maggiore, senza chiamare max().'],
155:['any risponde “almeno uno”, all risponde “tutti”. Le due lambda devono quindi verificare condizioni differenti sui punteggi.','Per any cerca un punteggio uguale a 100; per all controlla >= 50. Non usare una somma dei punteggi per decidere se ciascuno è promosso.'],
156:['La pulizia deve precedere la validazione: prima normalizza ogni email con map, poi scarta quelle non valide con filter.','Nel filtro conta esattamente un @ e richiedi almeno un carattere da entrambi i lati. Mantieni l’ordine e restituisci gli indirizzi ripuliti, non quelli originali.'],
157:['Il filtro elimina prima 0 e negativi. La trasformazione successiva sceglie il moltiplicatore in base alla parità del numero rimasto.','Concatena filter e map senza cicli. Usa il resto per 2 nella lambda di trasformazione: raddoppia i pari e triplica i dispari, senza cambiare l’ordine.'],
158:['La validazione dell’indice deve precedere inventory[index]. L’esercizio definisce validi soltanto gli indici non negativi entro la dimensione.','Controlla insieme index >= 0 e index < inventory.size(). Nell’altro ramo stampa il messaggio di posizione vuota, evitando qualsiasi accesso all’array.'],
159:['Convertire subito un testo non valido può nascondere il problema. Verifica prima che la stringa rappresenti un intero.','Usa is_valid_int() sul testo e chiama int() solo nel ramo valido. Un testo come 3.14 non è un intero; 007 è valido, ma va stampato come numero 7.'],
160:['Le clausole di guardia escono dalla funzione prima del calcolo per i due casi non ammessi: testo non intero e divisore zero.','Controlla prima il testo, poi converti e controlla 0. Nel caso valido dividi 100.0 e formatta la stringa con due decimali, senza stampare nella funzione.'],
161:['Il risultato di parse_level distingue successo e errore attraverso la chiave ok. Il chiamante sceglie cosa stampare in base a quel bool.','Valida prima il testo e poi l’intervallo 1–99. Nel dizionario di successo value è un int; in quello di errore deve esserci la spiegazione richiesta sotto error.'],
162:['La validità delle due stringhe di input è un controllo diverso dalla sicurezza della divisione. Entrambi devono precedere il risultato.','safe_divide restituisce un dizionario, non un numero in tutti i casi. Leggi ok prima di usare value, e nel ramo di errore mostra error senza accedere a value.'],
163:['L’inventario è un dizionario condiviso dal ciclo dei comandi. Una riga di input vuota chiude il programma senza creare un articolo.','Dichiara inventory prima del while e leggi una riga nuova a ogni giro. Se la riga è vuota usa break prima di dividerla e accedere ai suoi campi.'],
164:['add_item deve rifiutare un nome duplicato prima di scrivere nel dizionario, altrimenti cancellerebbe prezzo e scorte esistenti.','Dividi il comando nei campi e converti prezzo in float e scorte in int. Nella nuova voce conserva le chiavi price e stock.'],
165:['Un aggiornamento aggiunge quantity alle scorte correnti: non sostituisce le scorte con quantity. Il risultato va controllato prima di salvarlo.','Calcola una scorta candidata e rifiutala se negativa, lasciando invariato il valore precedente. Gestisci anche l’articolo assente prima di accedere al suo record.'],
166:['Il valore -1 permette di distinguere un articolo assente da uno presente con scorte pari a 0.','check_availability deve restituire un int senza stampare. Nel gestore del comando verifica il numero di campi prima di leggere il nome dell’articolo.'],
167:['Ogni vendita deve verificare articolo, quantità e scorte prima della sottrazione. Una vendita rifiutata non deve ridurre le scorte.','Elabora sales nell’ordine previsto, accumula il ricavo soltanto per le vendite riuscite e conserva gli aggiornamenti in inventory. Non applicare prima tutte le sottrazioni per controllarle dopo.'],
168:['Normalizza email e telefono prima di validare e cercare duplicati: due contatti con maiuscole diverse possono avere lo stesso indirizzo.','Conserva solo le cifre del telefono e richiedine esattamente dieci. Registra l’email fra quelle viste solo quando il contatto supera tutti i controlli.'],
169:['Conteggi e parole ripetute devono derivare dallo stesso testo normalizzato: minuscolo, punteggiatura rimossa e parti vuote escluse.','Conta le frequenze in un dizionario, poi ricava unique_count e le parole con conteggio maggiore di uno. Gestisci il testo vuoto prima di calcolare statistiche sulle lunghezze.'],
170:['Un singolo voto pari a 70 esclude lo studente: il requisito usa > 70 per tutti i voti, quindi serve all().','Separa prima i tre campi con ;, poi voti e materie con virgole. Calcola le medie come decimali e costruisci l’elenco delle materie senza duplicazioni, nell’ordine richiesto.'],
171:['greeter.gd deve dichiarare una classe accessibile al driver e un metodo statico: main.gd la usa senza creare un oggetto.','In greet distingui il nome vuoto dal nome presente. Restituisci il saluto usando il parametro, senza stampare dentro la classe né modificare main.gd.'],
172:['Il file car.gd definisce il tipo Car; gli oggetti creati da main.gd sono istanze separate di quel tipo.','Dichiara class_name Car e le proprietà richieste al livello della classe. Non spostarle dentro una funzione: il driver deve poterle leggere dall’istanza.'],
173:['Ogni istanza di Student deve conservare i propri dati. Una proprietà di istanza non va dichiarata static.','Aggiungi le proprietà della consegna in student.gd. Controlla che modificare uno studente non cambi i dati dell’altro creato dal driver.'],
174:['Quando parametro e proprietà hanno lo stesso nome, self distingue il dato dell’oggetto dal valore ricevuto.','In set_info assegna i parametri alle proprietà tramite self. In describe leggi poi quelle proprietà, non variabili locali create soltanto in set_info.'],
175:['Deposito e prelievo devono aggiornare lo stesso saldo che get_balance restituisce. I metodi non ricevono ogni volta un saldo nuovo.','Controlla importi e disponibilità prima di modificare il saldo. Nei rami rifiutati restituisci l’esito richiesto e lascia il saldo invariato.'],
176:['Una proprietà conserva un dato dell’istanza fra chiamate successive. describe deve ricavare il testo dalle proprietà correnti.','Dichiara i nomi e i tipi indicati per Player e usa i loro valori nella descrizione. Non fissare nel testo i dati del solo giocatore dell’esempio.'],
177:['Godot chiama _init quando esegue Book.new con gli argomenti del driver. Qui devi inizializzare le proprietà del nuovo libro.','Usa self se i parametri hanno gli stessi nomi dei campi. describe deve restituire una stringa basata su quei campi, senza leggere nuovo input.'],
178:['La calcolatrice conserva un risultato corrente: ciascun metodo opera su quello stato e get_result lo espone.','Aggiorna lo stato solo per operazioni ammesse. La divisione per zero deve essere gestita senza corrompere il risultato precedente; clear deve ripristinare lo stato iniziale.'],
179:['Le variabili di istanza appartengono a ciascun conto; il dato statico è condiviso da tutti i conti della classe.','Aggiorna il valore condiviso nel punto previsto dalla creazione del conto, non ogni volta che describe viene chiamato. Due conti devono avere saldi indipendenti.'],
180:['Grader offre funzioni statiche di classificazione; Student conserva i dati del singolo studente e può crearli da una riga.','In from_line converti i campi numerici e crea una nuova istanza. Per letter e is_passing controlla i limiti delle fasce senza duplicare la logica in report.'],
181:['Il setter di health deve mantenere il valore fra 0 e max_health a ogni assegnazione, compresi danni e cure.','Conserva la vecchia salute prima di limitarne il nuovo valore. Stampa la sconfitta soltanto nel passaggio da salute positiva a 0, non ogni volta che ricevi di nuovo 0.'],
182:['Un getter può calcolare un valore da un’altra proprietà senza conservarne una copia che potrebbe diventare obsoleta.','Ricava la temperatura convertita dal valore corrente in ogni lettura. Non eseguire la conversione soltanto nel costruttore, perché il driver modifica la temperatura in seguito.'],
183:['Il prefisso _ segnala un membro interno per convenzione. check_password e change_password devono essere l’accesso controllato alla password.','Prima di cambiare la password verifica sia quella corrente sia la forza della nuova tramite _is_strong. Un tentativo rifiutato deve lasciare valida la password precedente.'],
184:['I conti hanno un saldo per istanza e un tasso condiviso. apply_interest deve usare il tasso corrente, anche se è stato cambiato dopo la creazione del conto.','Depositi, prelievi e setter devono applicare gli stessi vincoli a ogni chiamata. Non correggere soltanto il formato di display_info: i test controllano anche lo stato.'],
185:['Car eredita proprietà e comportamento di Vehicle attraverso extends. Non serve copiare i campi del genitore nella sottoclasse.','Conserva la relazione di ereditarietà e aggiungi honk nel file car.gd. Il costruttore del veicolo deve inizializzare i dati usati anche dall’auto.'],
186:['super permette di riutilizzare l’inizializzazione e il metodo del genitore, aggiungendo solo ciò che appartiene a Employee.','Nel costruttore passa al genitore gli argomenti di Person. In introduce combina il testo del metodo del genitore con i dati del dipendente, senza duplicare tutta la presentazione.'],
187:['La stessa chiamata area() deve produrre il calcolo adatto al tipo concreto: ogni sottoclasse ridefinisce il metodo del genitore.','Circle e Square devono usare le proprie dimensioni, non un’area costante. Lascia che describe richiami il metodo dell’oggetto, così l’override viene usato anche dal codice comune.'],
188:['In una catena di ereditarietà ogni costruttore inizializza la propria parte e delega quella ereditata al genitore.','Segui la catena Character, Warrior e Knight e applica ciascuna modifica una sola volta. Copiare la stessa inizializzazione su tutti i livelli può azzerare i valori impostati prima.'],
189:['is verifica l’appartenenza a un tipo, comprese le sue sottoclassi. Un Penguin è anche un Bird e un Animal.','Quando distingui casi diversi in describe, controlla prima i tipi più specifici. Per count_birds includi anche gli oggetti derivati da Bird.'],
190:['La paga mensile dipende dal tipo del dipendente: Payroll deve usare i metodi polimorfici degli oggetti ricevuti.','Gestisci i costruttori con super, poi gli override di monthly_pay. Non calcolare tutti gli stipendi con la formula della sola classe Employee.'],
191:['wheels e sound sono punti di variazione: describe può riusarli senza conoscere la classe concreta del veicolo.','Ridefinisci i metodi nelle sottoclassi appropriate e conserva lo stato aggiuntivo di Truck. Non sostituire il driver con controlli manuali sul nome del veicolo.'],
192:['Nel duck typing conta se l’oggetto supporta l’operazione richiesta, non soltanto da quale classe deriva.','In hit_all controlla has_method prima di chiamare take_damage. Gli oggetti che non espongono il metodo vanno ignorati, non trattati come giocatori con salute.'],
193:['Una classe astratta definisce il contratto ma non può essere istanziata come un metodo di pagamento concreto.','Completa i metodi astratti nelle sottoclassi con firme compatibili. Lascia nel genitore la parte comune di receipt e usa gli override per le differenze.'],
194:['Playable descrive le operazioni che Song e Video devono offrire. Playlist lavora con quel contratto, senza dipendere dai dettagli di ogni tipo.','Implementa tutti i metodi astratti richiesti e conserva in Playlist gli oggetti aggiunti. play_all e total_time devono usare ciascun oggetto nell’ordine di inserimento.'],
195:['Area e perimetro sono responsabilità delle forme; ShapeCalculator deve aggregare i risultati tramite il contratto comune.','Completa le formule nelle sottoclassi, poi il processamento nel calcolatore. Verifica che forme di tipi diversi contribuiscano al totale, compresa CustomShape.'],
196:['XP e livello sono dati interni dell’eroe. gain_xp è il punto che applica la progressione e i getter espongono lo stato senza modificarlo.','Un incremento può attraversare più soglie: non fermarti al primo livello se restano XP sufficienti. Non lasciare che una lettura dei getter assegni nuovi punti.'],
197:['target accetta soltanto valori da 10 a 30; mode soltanto heat, cool e off. Un valore non valido va rifiutato, conservando la proprietà precedente.','Imposta last_error nel ramo rifiutato e svuotalo dopo un’assegnazione valida. Il costruttore deve assegnare target attraverso la proprietà, così passa dallo stesso setter.'],
198:['Restituire direttamente l’array interno permette a chi lo riceve di modificare la playlist senza usare add o remove.','get_titles deve produrre una copia separata dei titoli. Modificare quell’array dall’esterno non deve alterare il conteggio o gli elementi della playlist originale.'],
199:['Le proprietà calcolate devono riflettere gli articoli attuali dell’ordine. Un totale memorizzato una volta sola diventerebbe vecchio dopo add_item.','Mantieni i dati interni e calcola i valori esposti dai getter. Non aggiungere un setter a una proprietà che la consegna definisce di sola lettura.'],
200:['Il registro gestisce l’identità degli studenti; il singolo Student conserva voti e corsi. Non mescolare i due livelli di dati.','Gestisci ID duplicati e assenti prima degli accessi, restituisci copie quando richiesto e applica la regola di spareggio in top_student. Eliminare uno studente non deve modificare gli altri.'],
201:['Counter espone tick, plus ed equals come metodi: GDScript non consente di ridefinire l’operatore +. Uguaglianza dei valori e identità degli oggetti sono controlli diversi.','plus deve creare un Counter nuovo, conservando il passo del chiamante e lasciando invariati i due operandi. equals confronta i valori; == fra i due oggetti controlla invece se sono la stessa istanza.'],
202:['Godot richiama _to_string quando deve rappresentare un oggetto come testo. Il metodo deve restituire una String senza stampare.','Componi prima il testo della singola PlayingCard e riusalo per gli elementi della Hand. Ordine, separatori e caso della mano vuota devono essere gestiti esplicitamente.'],
203:['L’iteratore usa uno stato per ricordare la posizione corrente. _iter_init prepara il primo elemento e segnala se esiste.','_iter_next avanza una sola posizione e restituisce false alla fine; _iter_get legge l’elemento corrente senza avanzare. Verifica anche una Bookshelf vuota.'],
204:['La lista personalizzata deve conservare un array interno coerente fra append, pop, letture, scritture e iterazione.','Controlla gli indici prima dell’accesso e applica le regole per la lista vuota. concat e _to_string devono usare i dati della lista, non produrre un risultato fisso.'],
205:['Dichiarare un segnale ne definisce il nome e gli argomenti; emetterlo notifica chi è già collegato.','In deliver emetti il segnale con il messaggio ricevuto. Non chiamare direttamente il callback del driver e non sostituire il segnale con una stampa.'],
206:['I tick cambiano il tempo rimasto della bomba. L’esplosione è una transizione che deve avvenire una sola volta.','Emetti beeped con gli argomenti previsti e exploded quando raggiungi la fine. Dopo l’esplosione altri tick non devono ripetere lo stesso evento.'],
207:['watch e ignore gestiscono una connessione precisa tra il segnale di Target e il callback del tabellone.','Prima di collegare o scollegare controlla is_connected. Una seconda watch non deve raddoppiare i punti assegnati da un singolo colpo.'],
208:['Il segnale deve trasportare i dati che descrivono il cambiamento di saldo o il motivo del fallimento.','Aggiorna il saldo prima di emettere balance_changed. Per un acquisto impossibile lascia invariato il saldo ed emetti purchase_failed con gli argomenti richiesti.'],
209:['Health mantiene l’invariante fra 0 e il massimo; HealthBar osserva i cambiamenti tramite segnali, non cambiando la salute da sola.','Limita danni e cure, emetti gli eventi solo quando dovuti e gestisci la sostituzione dell’oggetto osservato. Restare a 0 non deve ripetere la morte a ogni chiamata.'],
210:['La composizione fa possedere un oggetto Weapon al cavaliere: equip cambia il componente usato, non il tipo della classe Knight.','Calcola l’attacco con l’arma attualmente equipaggiata. Dopo drop il riferimento può essere null: gestisci l’attacco senza arma senza leggere proprietà da un oggetto assente.'],
211:['La classe interna rappresenta una voce della classifica; Leaderboard deve conservare e confrontare quelle voci.','Aggiorna i punteggi secondo la regola di submit e applica lo spareggio in best. Una classifica vuota deve produrre il risultato previsto, non una voce inventata.'],
212:['Una Part che è Node diventa componente del Robot quando entra nel suo albero. Le parti devono restare oggetti distinti.','Aggiungi ciascuna parte al robot come richiesto e calcola total_power sui componenti effettivamente presenti. Non sommare soltanto l’ultima potenza ricevuta.'],
213:['RefCounted viene gestito dai riferimenti; un Enemy che è Node ha invece un ciclo di vita nell’albero. La morte deve aggiornare entrambi lo stato e la gestione del nodo.','In spawn registra gli oggetti creati, in hit tratta gli assenti e i nemici già sconfitti, in alive conta soltanto quelli ancora validi e vivi.'],
214:['L’enum appartiene alla classe Potion: i valori si usano attraverso il tipo che li dichiara. from_text traduce il comando nel valore dell’enum.','Centralizza la conversione in from_text. Nel riepilogo di Belt visita i tipi nell’ordine dell’enum e conta le pozioni presenti: anche un tipo assente deve avere una riga con conteggio e totale pari a 0.'],
215:['La Facade offre un punto d’ingresso che coordina musica, mappa e HUD. I sottosistemi continuano a eseguire le proprie operazioni.','In start_level richiama i componenti nell’ordine richiesto; in quit_level esegui le operazioni di chiusura. Non riprodurre soltanto le loro stampe dentro la Facade.'],
216:['Il Singleton conserva una sola istanza condivisa. get_instance deve creare ScoreManager soltanto quando ancora non esiste.','Memorizza l’istanza in un membro statico e restituiscila alle chiamate successive. Coin.collect deve aggiungere punti allo stesso gestore, senza crearne uno nuovo per ogni moneta.'],
217:['La Factory sceglie quale classe concreta creare a partire dal testo del tipo richiesto. Il resto del programma usa il contratto Enemy.','Normalizza il nome del tipo prima della scelta e gestisci il tipo sconosciuto come previsto. Passa i dati del nemico al costruttore invece di usare nomi fissi.'],
218:['Observer separa chi cambia la temperatura da chi la mostra. Il collegamento degli osservatori deve essere idempotente.','Usa is_connected in attach e detach. Quando cambia la temperatura emetti il segnale una volta: il numero di notifiche dipende dagli osservatori ancora collegati.'],
219:['La strategia di sconto è un oggetto sostituibile: Cart deve delegare il calcolo alla strategia scelta.','Gestisci nessuno sconto, sconto percentuale e fisso attraverso lo stesso contratto. Il totale finale non può diventare negativo, anche se lo sconto supera il prezzo.'],
220:['Un comando conserva ciò che serve sia per eseguire sia per annullare l’azione. La cronologia si annulla in ordine inverso rispetto all’esecuzione.','Aggiungi alla cronologia il comando eseguito e usa l’ultimo elemento per undo_last. Con cronologia vuota non annullare nulla e non estrarre un elemento inesistente.'],
221:['L’Adapter espone l’interfaccia del sensore moderno usando un termometro che restituisce Fahrenheit e un codice.','Delega la lettura all’oggetto legacy e converti con (F - 32) * 5.0 / 9.0. Il divisore decimale evita di perdere la parte frazionaria.'],
222:['Ogni Decorator avvolge una bevanda e aggiunge il proprio contributo, invece di sostituire tutto ciò che era già presente.','Per costo e descrizione parti dal risultato dell’oggetto avvolto. Il formato Large deve rispettare l’ordine dei decorator: applicarlo prima o dopo un’aggiunta può cambiare il prezzo.'],
223:['Il Template Method fissa la sequenza comune di esportazione; header, format_row e footer sono i punti che possono cambiare nelle sottoclassi.','In export_rows richiama gli hook nell’ordine previsto e gestisci quelli che restituiscono una stringa vuota. Non aggiungere righe vuote solo perché un hook non produce contenuto.'],
224:['Lo State rappresenta il comportamento della porta nello stato corrente. Una richiesta può cambiare stato oppure essere rifiutata senza modificarlo.','Delega handle_action allo stato attuale e assegna il nuovo stato soltanto per transizioni ammesse. Verifica sequenze di azioni, non soltanto ogni azione a partire da una porta chiusa.'],
225:['Il Composite usa lo stesso contratto per file e cartelle. Una cartella calcola i propri risultati aggregando quelli dei figli, anche quando sono altre cartelle.','Per dimensioni e conteggio visita ricorsivamente i figli. Per list_lines aumenta il rientro solo scendendo di un livello e conserva l’ordine di aggiunta.'],
226:['La prima Library deve predisporre lo stato e la propria rappresentazione; i comandi di prestito arriveranno nei passi successivi.','Inizializza i contenitori della biblioteca per ogni istanza e usa il nome passato al costruttore in _to_string. Non condividere cataloghi fra due biblioteche diverse.'],
227:['Book e User conservano i propri identificativi e dati. _to_string descrive lo stato corrente, compreso quello di disponibilità o prestito.','Inizializza le proprietà nei rispettivi costruttori e mantieni coerenti i valori iniziali. Non marcare un libro come prestato soltanto per visualizzarlo nel catalogo.'],
228:['Il prestito deve aggiornare sia il libro sia l’elenco dei prestiti dell’utente. Tutti i controlli devono precedere le modifiche.','Cerca prima libro e utente e rispetta l’ordine degli errori indicato. Se il prestito è rifiutato, nessuno dei due oggetti deve cambiare stato.'],
229:['La ricerca per titolo non distingue maiuscole e minuscole, ma deve restituire i libri originali del catalogo.','Confronta la query e il titolo normalizzati con to_lower(). Conserva l’ordine dei libri e restituisci un array vuoto quando non ci sono corrispondenze.'],
230:['Le statistiche devono derivare dai contenitori e dallo stato attuale dei libri e degli utenti, non da contatori lasciati al valore iniziale.','Conta separatamente gli oggetti totali e quelli prestati o disponibili secondo le chiavi richieste. Ricontrolla le statistiche dopo un prestito riuscito e dopo uno rifiutato.'],
231:['La restituzione è l’operazione inversa del prestito: deve liberare il libro e rimuoverlo dai prestiti del proprietario corretto.','Verifica appartenenza e identificativi prima di modificare entrambi gli oggetti. Una restituzione ripetuta o richiesta da un altro utente deve essere rifiutata senza alterare lo stato.'],
232:['Iscrizioni e completamenti collegano Student e Course: le due viste della relazione devono restare coerenti.','Controlla capacità, iscrizione duplicata e presenza dello studente prima delle modifiche. Rimuovere un’iscrizione deve aggiornare anche i completamenti e gli elenchi correlati previsti.'],
233:['Il trasferimento fra conti è un’operazione unica: se il prelievo è rifiutato, il conto destinatario non deve ricevere denaro.','Delega i vincoli al tipo concreto del conto, aggiorna i due saldi solo dopo i controlli e registra le transazioni riuscite nella cronologia. I tentativi falliti non sono ricavi o movimenti riusciti.'],
234:['I personaggi condividono salute, livelli e abilità, ma le sottoclassi definiscono statistiche e potenza d’attacco differenti.','Controlla vita, indice dell’abilità e mana prima di applicare danni o costi. Il segnale defeated riguarda il passaggio da vivo a sconfitto: non deve ripetersi su un personaggio già sconfitto.'],
235:['Vehicle, Rental e RentalAgency hanno responsabilità diverse: disponibilità del veicolo, stato del noleggio e gestione del catalogo.','Crea il noleggio e avanza l’ID solo dopo tutti i controlli. Una restituzione riuscita deve terminare il Rental e liberare il Vehicle; ripeterla non deve creare ricavi o nuovi noleggi.']
 };
 for(const lesson of window.LESSONS_DATA||[]){
   const pair=hints[lesson.manualLessonNumber];
   if(!pair||pair.length!==2)throw Error('Indizi mancanti per la lezione '+lesson.manualLessonNumber);
   lesson.hints=pair.map((text,i)=>({level:i+1,icon:i?'wrench':'lightbulb',label:i?'Passaggi e casi limite':'Idea da applicare',text}));
 }
})();
